// ADR 0371, 0372 (T20t): property tracks into ECS fields through the binding table, and notifies to behaviours, in a
// headless Engine through the public API (`myco`). The clips are `props.anim` and `notifies.anim`, generated by
// `native/anim/crates/anim-wasm/tests/property_fixtures.rs` (its header lists their tracks). Time comes from
// `engine.step(dt)` only. Property values are compared at 1e-3: the compressed clip's property tracks keep an absolute
// error under 1e-4 (anim-compress's default property bound), and the playhead is the product's clock.
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import {
  AnimationEvents,
  Animator,
  Assets,
  Audio,
  BallJoint,
  Engine,
  GameBehavior,
  GameObject,
  Light,
  MeshRenderer,
  Skeleton,
  SkinnedMeshRenderer,
  SpriteRenderer,
  Color,
  type AnimationEvent,
} from "../../../../myco";
import { applyTestPlugins } from "../../../testPlugins";
import { instanceForSkeleton } from "../skeletonInstances";

const fixtureUrl = (name: string) => new URL(`../wasm/fixtures/${name}`, import.meta.url);
const SKEL = "anim/small.skel";
const PROPS = "anim/props.anim";
const NOTIFIES = "anim/notifies.anim";
const dt = 1 / 30;
const TOL = 1e-3;

let engine: Engine;
const steps = (n: number) => {
  for (let i = 0; i < n; i++) engine.step(dt);
};

/** What the hero's behaviour heard: method calls and the frame's `AnimationEvents`. */
const calls: { method: string; e: AnimationEvent }[] = [];
const buffered: AnimationEvent[] = [];
const updateArgs: unknown[][] = [];

class Probe extends GameBehavior {
  footstep(e: AnimationEvent) {
    calls.push({ method: "footstep", e });
  }
  swing(e: AnimationEvent) {
    calls.push({ method: "swing", e });
  }
  update(...args: unknown[]) {
    if (args.length) updateArgs.push(args);
  }
  lateUpdate() {
    buffered.push(...AnimationEvents.read());
  }
}

interface Hero {
  node: GameObject;
  anim: Animator;
  lamp: Light;
  body: MeshRenderer;
  sprite: SpriteRenderer;
  trail: GameObject;
  face: SkinnedMeshRenderer;
  joint: BallJoint;
  feet: GameObject;
}

const made: GameObject[] = [];

async function hero(): Promise<Hero> {
  const node = GameObject.create("Hero");
  made.push(node);
  node.addComponent(Skeleton, { skeleton: SKEL });
  const anim = node.addComponent(Animator);
  node.addComponent(Probe);
  const child = (name: string) => GameObject.create(name, { parent: node });
  const lamp = child("Lamp").addComponent(Light, { type: "point" });
  const body = child("Body").addComponent(MeshRenderer);
  const sprite = child("Sprite").addComponent(SpriteRenderer);
  const trail = child("Trail");
  const face = child("Face").addComponent(SkinnedMeshRenderer);
  const joint = child("Joint").addComponent(BallJoint);
  const feet = child("Feet");
  feet.transform!.position = [1, 2, 3];
  await vi.waitFor(() => expect(instanceForSkeleton(engine.world, node)).not.toBe(0));
  return { node, anim, lamp, body, sprite, trail, face, joint, feet };
}

/** Plays `clip` and steps with dt 0 until it shows (loaded and sent): no time passes. */
async function start(anim: Animator, clip: string): Promise<void> {
  anim.play(clip);
  await vi.waitFor(() => {
    engine.step(0);
    expect(anim.state().name).toBe(clip);
  });
}

function destroyAll(): void {
  for (const n of made.splice(0)) if (n.isValid) GameObject.destroy(n);
  engine.step(0);
  calls.length = 0;
  buffered.length = 0;
  updateArgs.length = 0;
}

beforeAll(async () => {
  Assets.clearSources();
  Assets.addSource(
    Assets.fromObject({
      [SKEL]: fixtureUrl("small.skel").href,
      [PROPS]: fixtureUrl("props.anim").href,
      [NOTIFIES]: fixtureUrl("notifies.anim").href,
    }),
  );
  engine = await Engine.create({ headless: true });
});

afterAll(() => engine?.dispose());

describe("property tracks (ADR 0371)", () => {
  it("drive a light's intensity, a material colour, a sprite slice, activation, a morph weight and a joint target", async () => {
    const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
    const h = await hero();
    await start(h.anim, PROPS);
    steps(6); // t = 0.2
    const t = 6 * dt;
    expect(h.lamp.intensity).toBeCloseTo(2 * t, 3);
    const c = h.body.getMaterialProperty("color");
    expect(c).toBeInstanceOf(Color);
    expect((c as Color).r).toBeCloseTo(t, 3);
    expect((c as Color).g).toBeCloseTo(0.5, 3);
    expect((c as Color).b).toBeCloseTo(1 - t, 3);
    expect(h.body.material).toBe(""); // an override on this renderer, not the asset
    expect(h.sprite.sprite).toBe("sheet.png#run_0");
    expect(h.trail.active).toBe(false);
    expect(h.face.morphWeights[1]).toBeCloseTo(t, 3);
    const q = h.joint.drive.targetRotation;
    expect(q.y).toBeCloseTo(Math.sin((Math.PI / 4) * t), 3);
    expect(q.w).toBeCloseTo(Math.cos((Math.PI / 4) * t), 3);
    expect(Math.abs(q.x) + Math.abs(q.z)).toBeLessThan(TOL);

    steps(4); // t ≈ 0.33: the trail is on
    expect(h.trail.active).toBe(true);
    expect(h.sprite.sprite).toBe("sheet.png#run_0");
    steps(6); // t ≈ 0.53: the slice has stepped
    expect(h.sprite.sprite).toBe("sheet.png#run_3");
    expect(h.lamp.intensity).toBeCloseTo(2 * 16 * dt, 3);
    steps(8); // t = 0.8: the trail is off again
    expect(h.trail.active).toBe(false);
    warn.mockRestore();
    destroyAll();
  });

  it("leaves tracks with a missing target unbound with one warning per clip and node, and binds them once the target appears", async () => {
    const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
    const h = await hero();
    await start(h.anim, PROPS);
    steps(3);
    const misses = () => warn.mock.calls.map((c) => String(c[0])).filter((m) => m.includes("tracks with no target"));
    expect(misses()).toHaveLength(1);
    expect(misses()[0]).toContain('"Ghost" engine.Light.intensity (no such node)');
    expect(misses()[0]).toContain('"Lamp" engine.Light.type');
    expect(misses()[0]).toContain("Hero");
    expect(h.lamp.type).toBe("point"); // the enum is left alone
    steps(3);
    expect(misses()).toHaveLength(1);

    // The hierarchy changes: the table rebinds and the Ghost track drives the new light; no second warning.
    const ghost = GameObject.create("Ghost", { parent: h.node }).addComponent(Light, { intensity: 9 });
    steps(3); // t = 0.3
    expect(ghost.intensity).toBeCloseTo(9 * dt, 3);
    expect(misses()).toHaveLength(1);

    // A renamed node unbinds its track: the lamp keeps its last value.
    const before = h.lamp.intensity;
    h.lamp.node.name = "Lamp2";
    steps(3);
    expect(h.lamp.intensity).toBe(before);
    warn.mockRestore();
    destroyAll();
  });
});

describe("notifies (ADR 0372)", () => {
  it("call the behaviour's methods with args and phases, and fill AnimationEvents", async () => {
    const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
    const h = await hero();
    await start(h.anim, NOTIFIES);
    steps(9); // t = 0.3: footstep at 0.25
    expect(calls.map((c) => c.method)).toEqual(["footstep"]);
    const step = calls[0]!.e;
    expect(step.node).toBe(h.node);
    expect(step.animator).toBe(h.anim);
    expect({ method: step.method, phase: step.phase, args: step.args, clip: step.clip }).toEqual({ method: "footstep", phase: "instant", args: ["L", 2], clip: NOTIFIES });
    expect(step.time).toBeCloseTo(0.25, 5);
    expect(buffered).toHaveLength(1);
    expect(buffered[0]).toBe(step); // the same record goes to the buffer

    steps(6); // t = 0.5: swing began at 0.4 and ticks; update at 0.5 is reserved
    const swings = calls.filter((c) => c.method === "swing").map((c) => c.e);
    expect(swings[0]!.phase).toBe("begin");
    expect(swings[0]!.args).toEqual([JSON.stringify({ power: 3 })]);
    expect(swings.slice(1).every((e) => e.phase === "tick")).toBe(true);
    expect(swings.length).toBeGreaterThan(1);
    expect(updateArgs).toEqual([]); // `update` never gets an event
    expect(buffered.some((e) => e.method === "update" && e.phase === "instant")).toBe(true);
    expect(warn.mock.calls.some((c) => String(c[0]).includes('"update", which is reserved'))).toBe(true);

    steps(9); // t = 0.8: swing ended at 0.7
    const phases = calls.filter((c) => c.method === "swing").map((c) => c.e.phase);
    expect(phases[phases.length - 1]).toBe("end");
    expect(phases.filter((p) => p === "begin")).toHaveLength(1);
    expect(phases.filter((p) => p === "end")).toHaveLength(1);
    expect(buffered.filter((e) => e.method === "swing")).toHaveLength(phases.length);
    // The control key (0.6 s) reaches the particlePlay handler (T22t); its target "Sparks" isn't there: one warning, skipped.
    expect(warn.mock.calls.filter((c) => String(c[0]).includes('"particlePlay" key of') && String(c[0]).includes('"Sparks"'))).toHaveLength(1);
    warn.mockRestore();
    destroyAll();
  });

  it("play audio keys through Audio.play at the track's node when audio is active, and skip them when it isn't", async () => {
    const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
    const play = vi.spyOn(Audio, "play");
    let h = await hero();
    await start(h.anim, NOTIFIES);
    steps(10); // t ≈ 0.33: the audio key at 0.3
    expect(play).toHaveBeenCalledTimes(1);
    const [asset, options] = play.mock.calls[0]!;
    expect(asset).toBe("asset:sfx/step.wav");
    expect(options).toMatchObject({ volume: 0.5, parameters: { surface: 2 } });
    expect(options!.position).toEqual({ x: 1, y: 2, z: 3 });
    destroyAll();

    play.mockClear();
    try {
      applyTestPlugins(["myco.audio"]);
      h = await hero();
      await start(h.anim, NOTIFIES);
      steps(10);
      expect(play).not.toHaveBeenCalled();
      expect(calls.map((c) => c.method)).toContain("footstep"); // notifies still run
      destroyAll();
    } finally {
      applyTestPlugins();
      play.mockRestore();
      warn.mockRestore();
    }
  });
});
